//! `docs/dev/kernel-inventory-audit.md` is generated by
//! `crates/compiler/scripts/kernel_inventory_audit.py` (see that script's
//! module docstring for the method). This mirrors
//! `supported_latex.rs::generated_artifacts_are_current`: fail CI when the
//! checked-in document disagrees with a fresh run, instead of letting the
//! inventory this audit exists to fix drift silently the way the original
//! hand-written version did (PR #361 needed a full re-derivation twice in
//! one day and moved a third of its rows in about 24 hours).

use std::path::PathBuf;
use std::process::Command;

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

const REGENERATE: &str = "run crates/compiler/scripts/kernel_inventory_audit.py";

#[test]
fn kernel_inventory_audit_is_current() {
    let script = crate_dir().join("scripts/kernel_inventory_audit.py");
    let doc_path = crate_dir().join("../../docs/dev/kernel-inventory-audit.md");
    let out_path = std::env::temp_dir().join(format!(
        "kernel-inventory-audit-{}-{:?}.md",
        std::process::id(),
        std::thread::current().id()
    ));

    // `CARGO_BIN_EXE_flashtex-compiler` is the binary Cargo already built for
    // this test run (same package, `[[bin]] name = "flashtex-compiler"`), so
    // the script does not need its own nested `cargo build`.
    let status = Command::new("python3")
        .arg(&script)
        .arg("--bin")
        .arg(env!("CARGO_BIN_EXE_flashtex-compiler"))
        .arg("--out")
        .arg(&out_path)
        .status()
        .unwrap_or_else(|e| panic!("run {}: {e}", script.display()));
    assert!(
        status.success(),
        "{} exited non-zero",
        script.display()
    );

    let generated = std::fs::read_to_string(&out_path)
        .unwrap_or_else(|e| panic!("read {}: {e}", out_path.display()));
    let _ = std::fs::remove_file(&out_path);
    let current = std::fs::read_to_string(&doc_path)
        .unwrap_or_else(|e| panic!("read {}: {e}", doc_path.display()));

    assert!(
        generated == current,
        "docs/dev/kernel-inventory-audit.md is stale; {REGENERATE}"
    );
}
